package com.tanidikvar.api.evaluation.repository;
import com.tanidikvar.api.evaluation.dto.*;import java.sql.*;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class EvaluationRepository{
 private final JdbcTemplate jdbc;public EvaluationRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private EvaluationResponse map(ResultSet r,int n)throws SQLException{UUID program=r.getObject("program_id",UUID.class);return new EvaluationResponse(r.getObject("id",UUID.class),r.getObject("author_id",UUID.class),r.getString("author_name"),r.getObject("university_id",UUID.class),program==null?r.getObject("university_department_id",UUID.class):program,r.getInt("rating"),r.getString("body"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant(),r.getLong("version"));}
 private static final String SELECT="SELECT e.*,concat_ws(' ',p.first_name,p.last_name) author_name FROM evaluations e JOIN user_profiles p ON p.user_id=e.author_id AND p.deleted_at IS NULL ";
 private boolean normalized(UUID university,UUID program){return program!=null&&Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM programs WHERE id=? AND university_id=? AND deleted_at IS NULL)",Boolean.class,program,university));}
 public boolean context(UUID university,UUID program){return program==null?Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM universities WHERE id=? AND deleted_at IS NULL)",Boolean.class,university)):normalized(university,program)||Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM university_departments WHERE id=? AND university_id=? AND deleted_at IS NULL)",Boolean.class,program,university));}
 public EvaluationResponse save(UUID author,EvaluationRequest request){UUID id=UUID.randomUUID();UUID saved;if(request.programId()==null||!normalized(request.universityId(),request.programId()))saved=jdbc.queryForObject("INSERT INTO evaluations(id,author_id,university_id,university_department_id,rating,body) VALUES (?,?,?,?,?,?) ON CONFLICT(author_id,university_id,university_department_id) DO UPDATE SET rating=excluded.rating,body=coalesce(excluded.body,evaluations.body),deleted_at=NULL,updated_at=CURRENT_TIMESTAMP,version=evaluations.version+1 RETURNING id",UUID.class,id,author,request.universityId(),request.programId(),request.rating(),request.body()==null?null:request.body().strip());else saved=jdbc.queryForObject("INSERT INTO evaluations(id,author_id,university_id,program_id,rating,body) VALUES (?,?,?,?,?,?) ON CONFLICT(author_id,university_id,program_id) WHERE program_id IS NOT NULL DO UPDATE SET rating=excluded.rating,body=coalesce(excluded.body,evaluations.body),deleted_at=NULL,updated_at=CURRENT_TIMESTAMP,version=evaluations.version+1 RETURNING id",UUID.class,id,author,request.universityId(),request.programId(),request.rating(),request.body()==null?null:request.body().strip());jdbc.update("INSERT INTO evaluation_ratings(evaluation_id,criterion_key,rating) VALUES (?,?,?) ON CONFLICT(evaluation_id,criterion_key) DO UPDATE SET rating=excluded.rating,updated_at=CURRENT_TIMESTAMP",saved,request.criterionKey().name(),request.rating());
 jdbc.update("UPDATE evaluations SET rating=(SELECT round(avg(rating)) FROM evaluation_ratings WHERE evaluation_id=?) WHERE id=?",saved,saved);
 return find(saved);}
 public EvaluationResponse find(UUID id){return jdbc.query(SELECT+"WHERE e.id=? AND e.deleted_at IS NULL",this::map,id).stream().findFirst().orElseThrow();}
 private String contextSql(UUID university,UUID program){return normalized(university,program)?"program_id IS NOT DISTINCT FROM ?":program==null?"university_department_id IS NOT DISTINCT FROM ? AND e.program_id IS NULL":"university_department_id IS NOT DISTINCT FROM ?";}
 public List<EvaluationResponse> list(UUID university,UUID program,int page,int size){return jdbc.query(SELECT+"WHERE e.university_id=? AND e."+contextSql(university,program)+" AND e.deleted_at IS NULL ORDER BY e.created_at DESC,e.id LIMIT ? OFFSET ?",this::map,university,program,size,page*size);}
 public long count(UUID university,UUID program){return jdbc.queryForObject("SELECT count(*) FROM evaluations e WHERE university_id=? AND "+contextSql(university,program)+" AND deleted_at IS NULL",Long.class,university,program);}
 public EvaluationSummaryResponse summary(UUID university,UUID program){return jdbc.queryForObject("SELECT coalesce(round(avg(coalesce((SELECT avg(r.rating) FROM evaluation_ratings r WHERE r.evaluation_id=e.id),e.rating)),2),0) average,count(*) total FROM evaluations e WHERE university_id=? AND "+contextSql(university,program)+" AND deleted_at IS NULL",(r,n)->new EvaluationSummaryResponse(r.getDouble("average"),r.getLong("total")),university,program);}
 public List<EvaluationCriterionResponse> criteria(UUID university,UUID program){
 var rows=jdbc.query("SELECT r.criterion_key,r.rating,count(*) votes FROM evaluation_ratings r JOIN evaluations e ON e.id=r.evaluation_id WHERE e.university_id=? AND e."+contextSql(university,program)+" AND e.deleted_at IS NULL GROUP BY r.criterion_key,r.rating",(r,n)->new Object[]{r.getString("criterion_key"),r.getInt("rating"),r.getLong("votes")},university,program);
 return Arrays.stream(EvaluationCriterion.values()).map(key->{var distribution=new ArrayList<Long>(Collections.nCopies(5,0L));for(var row:rows)if(key.name().equals(row[0]))distribution.set((Integer)row[1]-1,(Long)row[2]);long count=distribution.stream().mapToLong(Long::longValue).sum();long total=0;for(int i=0;i<5;i++)total+=(i+1)*distribution.get(i);return new EvaluationCriterionResponse(key,key.label(),count==0?0:(double)total/count,count,distribution);}).toList();
 }
 public List<EvaluationRatingResponse> myRatings(UUID author,UUID university,UUID program){return jdbc.query("SELECT r.criterion_key,r.rating FROM evaluation_ratings r JOIN evaluations e ON e.id=r.evaluation_id WHERE e.author_id=? AND e.university_id=? AND e."+contextSql(university,program)+" AND e.deleted_at IS NULL",(r,n)->new EvaluationRatingResponse(EvaluationCriterion.valueOf(r.getString("criterion_key")),r.getInt("rating")),author,university,program);}
}
